import assert from 'node:assert/strict';
import { execFileSync, spawn } from 'node:child_process';
const BOT = process.argv[2];
const { decide, recordDismissal, optOut } = await import(BOT);
const F = { proactiveEnabled: true };
const u = (o={}) => ({ id:'u'+Math.random(), timezone:'America/New_York', deviceTimezone:undefined, consents:{marketing:true}, createdAt:'2026-01-01T00:00:00Z', ...o });
const c = (id='c'+Math.random(), type='checkin') => ({ id, type });
const at = (s) => new Date(s);
const noon = at('2026-10-23T16:00:00Z'); // 12:00 NY
let r;
r = await decide({user:u(),candidate:c(),now:noon,flags:F}); assert.equal(r.send,true); assert.equal(r.reason,null);
assert.equal((await decide({user:u(),candidate:c(),now:noon,flags:{proactiveEnabled:false}})).send,false);
assert.equal((await decide({user:u({consents:undefined}),candidate:c(),now:noon,flags:F})).send,false);
assert.equal((await decide({user:u({consents:{}}),candidate:c(),now:noon,flags:F})).send,false);
assert.equal((await decide({user:u({consents:{marketing:false}}),candidate:c(),now:noon,flags:F})).send,false);
// quiet hours: 03:00 NY
assert.equal((await decide({user:u(),candidate:c(),now:at('2026-10-23T07:00:00Z'),flags:F})).send,false);
// placeholder UTC, no device => unknown
assert.equal((await decide({user:u({timezone:'UTC'}),candidate:c(),now:noon,flags:F})).send,false);
assert.equal((await decide({user:u({timezone:undefined}),candidate:c(),now:noon,flags:F})).send,false);
// placeholder UTC + device Tokyo: noon UTC = 21:00 Tokyo => no; 01:00 UTC = 10:00 Tokyo => yes
assert.equal((await decide({user:u({timezone:'UTC',deviceTimezone:'Asia/Tokyo'}),candidate:c(),now:noon,flags:F})).send,false);
assert.equal((await decide({user:u({timezone:'UTC',deviceTimezone:'Asia/Tokyo'}),candidate:c(),now:at('2026-10-23T01:00:00Z'),flags:F})).send,true);
// device overrides saved when traveling
assert.equal((await decide({user:u({deviceTimezone:'Asia/Tokyo'}),candidate:c(),now:noon,flags:F})).send,false);
// invalid zones
assert.equal((await decide({user:u({timezone:'Mars/Base'}),candidate:c(),now:noon,flags:F})).send,false);
// once per day, id idempotency, next day ok
const a = u();
assert.equal((await decide({user:a,candidate:c('x1'),now:noon,flags:F})).send,true);
assert.equal((await decide({user:a,candidate:c('x1'),now:noon,flags:F})).send,false);
assert.equal((await decide({user:a,candidate:c('x2'),now:at('2026-10-23T18:00:00Z'),flags:F})).send,false);
assert.equal((await decide({user:a,candidate:c('x3'),now:at('2026-10-24T16:00:00Z'),flags:F})).send,true);
// different type same day ok, third blocked
assert.equal((await decide({user:a,candidate:c('t1','tip'),now:at('2026-10-24T17:00:00Z'),flags:F})).send,true);
assert.equal((await decide({user:a,candidate:c('t2','other'),now:at('2026-10-24T18:00:00Z'),flags:F})).send,false);
// dismissal backoff
const b = u();
await recordDismissal(b.id,'checkin',noon);
assert.equal((await decide({user:b,candidate:c(),now:at('2026-10-24T16:00:00Z'),flags:F})).send,false);
assert.equal((await decide({user:b,candidate:c(),now:at('2026-10-26T17:00:00Z'),flags:F})).send,true);
await recordDismissal(b.id,'checkin',at('2026-10-26T17:30:00Z'));
assert.equal((await decide({user:b,candidate:c(),now:at('2026-10-29T17:00:00Z'),flags:F})).send,false); // 4 days wait
assert.equal((await decide({user:b,candidate:c('tip9','tip'),now:at('2026-10-27T17:00:00Z'),flags:F})).send,true); // other type unaffected
// opt-out persists
const o = u(); await optOut(o.id,'checkin');
assert.equal((await decide({user:o,candidate:c(),now:noon,flags:F})).send,false);
assert.equal((await decide({user:o,candidate:c('tp','tip'),now:noon,flags:F})).send,true);
// restart persistence + multi-process race
const racer = u({id:'race'});
const code = `const m=await import(${JSON.stringify(BOT)});const r=await m.decide({user:${JSON.stringify(racer)},candidate:{id:'rc'+process.pid,type:'checkin'},now:new Date('2026-10-23T16:00:00Z'),flags:{proactiveEnabled:true}});console.log(r.send)`;
const outs = await Promise.all(Array.from({length:12},()=>new Promise(res=>{const p=spawn('node',['--input-type=module','-e',code],{env:process.env});let s='';p.stdout.on('data',d=>s+=d);p.on('close',()=>res(s.trim()));})));
assert.equal(outs.filter(x=>x==='true').length,1,outs.join());
// after "restart" (fresh processes) still blocked
const again = execFileSync('node',['--input-type=module','-e',code],{env:process.env}).toString().trim();
assert.equal(again,'false');
// no STATE_DIR => fail closed
console.log('ALL OK');
EOF
